App.boot({id:'transfers',title:'Transfers & Receiving',render(el){const {esc,icon,num,formGrid}=U,S=Store,db=S.db,fs=App.farm(),off=App.isOffice(),u=App.user(),all=App.scope()==='all';
 const rows=db.transfers.filter(x=>off&&all||x.farm===fs).slice().reverse();const awaiting=rows.filter(x=>x.received==null).length;
 el.innerHTML=`<div class="page-head"><div><p>${off?'Send stock from the main godown and track farm receiving.':'Confirm the quantity actually received at <b>'+esc(fs)+'</b> and print the receiving receipt.'}</p></div><div class="row">${App.scopeBar()}${off?`<button class="btn" id="send">${icon('truck')} Send stock</button>`:''}</div></div>
 ${awaiting?`<div class="alert info" style="margin-bottom:16px">${icon('info')}<span>${awaiting} transfer${awaiting>1?'s':''} awaiting farm receiving.</span></div>`:''}
 ${all?`<div class="card" style="margin-bottom:16px"><div class="card-head"><div><h3>All Farms — stock sent & received</h3><p>Combined record by item with per-farm breakdown below.</p></div></div><div id="sum"></div></div>`:''}<div class="card"><div class="card-head"><div><h3>Farm receiving — confirm quantity</h3><p>Stock transfers are movements, not expenses.</p></div></div><div id="t"></div></div>`;
 U.dataTable(document.getElementById('t'),{rows,emptyTitle:'No transfers yet',emptyText:off?'Use “Send stock” to move stock to a farm.':'Office has not sent stock to this farm yet.',filters:[{label:'Status',options:['Awaiting','Received'],get:x=>x.received==null?'Awaiting':'Received'},{label:'Item',options:S.ITEMS,get:x=>x.item}].concat(off?[{label:'Farm',options:S.FARMS,get:x=>x.farm}]:[]),columns:[
  {label:'ID',value:x=>x.id.slice(-5),html:x=>`<code>${esc(x.id.slice(-5))}</code>`},{label:'Date',value:x=>x.date},{label:'Farm',value:x=>x.farm},{label:'Item',value:x=>x.item},
  {label:'Sent',num:1,value:x=>x.qty},{label:'Received',num:1,value:x=>x.received??-1,html:x=>x.received==null?'<span class="badge warn">Awaiting</span>':num(x.received)},
  {label:'Difference',num:1,value:x=>x.received==null?0:x.qty-x.received,html:x=>x.received==null?'—':`<span class="${x.qty-x.received?'neg strong':''}">${num(x.qty-x.received)}</span>`},
  {label:'Action',sort:false,html:x=>x.received==null&&(!off||App.isOwner())?`<button class="btn sm" data-receive="${x.id}">${icon('check')} Receive</button>`:x.received!=null?`<button class="btn secondary sm" data-print="${x.id}">${icon('print')} Print / PDF</button>`:'<span class="muted small">Awaiting farm</span>'}]});
 App.bindScope(el);if(all)App.stockSummary(document.getElementById('sum'));const s=document.getElementById('send');if(s)s.onclick=()=>U.modal({title:'Send from main godown',submit:'Send stock',body:formGrid([{name:'Farm',label:'Farm',options:db.farms.filter(f=>!f.archived).map(f=>f.name),value:fs},{name:'Item',label:'Item',options:S.ITEMS.map(i=>[i,`${i} (available ${num(S.godownQty(i))})`])},{name:'Quantity',label:'Quantity',type:'number',attrs:'min="0.01" step="0.01"'}]),
  onSubmit:d=>{const qty=Number(d.Quantity);if(qty<=0||qty>S.godownQty(d.Item))throw Error('Insufficient main godown stock');db.transfers.push({id:U.uid(),farm:d.Farm,item:d.Item,qty,received:null,date:U.today()});S.log(`Sent ${qty} ${d.Item} to ${d.Farm}`);U.toast('Stock sent to '+d.Farm);App.refresh()}});
 U.on(el,'[data-receive]',b=>b.onclick=()=>{const x=db.transfers.find(t=>t.id===b.dataset.receive);U.modal({title:'Receive '+x.item+' at '+x.farm,submit:'Confirm received',body:formGrid([{name:'q',label:`Quantity actually received (sent ${x.qty})`,type:'number',value:x.qty,attrs:`min="0" max="${x.qty}" step="0.01"`}]),
  onSubmit:d=>{const q=Number(d.q);if(!Number.isFinite(q)||q<0||q>x.qty)throw Error('Received quantity must be 0 to sent quantity');x.received=q;x.receivedBy=u.role;x.receivedAt=new Date().toLocaleString();S.log(`Received ${q}/${x.qty} ${x.item} at ${x.farm}`);U.toast('Receiving confirmed');App.refresh()}})});
 U.on(el,'[data-print]',b=>b.onclick=()=>{const x=db.transfers.find(t=>t.id===b.dataset.print);
  App.print(App.docHead('Farm Stock Receiving Receipt','Receipt #'+x.id.slice(-5))+`<table><tbody><tr><th>Farm</th><td>${esc(x.farm)}</td><th>Date</th><td>${esc(x.receivedAt||x.date)}</td></tr><tr><th>Item</th><td>${esc(x.item)}</td><th>Received by</th><td>${esc(x.receivedBy||'—')}</td></tr></tbody></table><table><thead><tr><th>Sent</th><th>Received</th><th>Difference</th></tr></thead><tbody><tr><td>${x.qty}</td><td>${x.received}</td><td>${x.qty-x.received}</td></tr></tbody></table><div class="sign"><div>Farm Supervisor Signature</div><div>Office Verification</div></div>`)})}});
